SELECT COUNT(DISTINCT state) AS a, COUNTIF(age > 30) AS b, ANY_VALUE(city) AS c, ARRAY_AGG(id ORDER BY id LIMIT 3) AS d, STRING_AGG(first_name, ',' ORDER BY id) AS e, APPROX_COUNT_DISTINCT(id) AS f, APPROX_QUANTILES(age, 4) AS g, APPROX_TOP_COUNT(state, 3) AS h, LOGICAL_AND(age > 0) AS i, LOGICAL_OR(age > 0) AS j, BIT_XOR(id) AS k, MAX_BY(first_name, age) AS l, MIN_BY(first_name, age) AS m, CORR(age, id) AS n, STDDEV(age) AS o, VARIANCE(age) AS p, SUM(age) AS q FROM `kumosql.kumosql_messy.raw_users`
